css:
.d-hc{width:100%;max-width:340px}
.d-hc-svg{display:block;width:100%;height:auto}
.d-hc-cell{stroke:var(--bg);stroke-width:1}
.d-hc-legend{display:flex;align-items:center;gap:4px;margin-top:6px;font-family:var(--font-mono);font-size:8px;color:var(--faint)}
.d-hc-legend i{width:9px;height:9px;border-radius:2px;display:block}
.d-hc-legend i[data-l="0"]{background:color-mix(in srgb,var(--ink) 6%,var(--paper))}
.d-hc-legend i[data-l="1"]{background:color-mix(in srgb,var(--ink) 18%,var(--paper))}
.d-hc-legend i[data-l="2"]{background:color-mix(in srgb,var(--ink) 34%,var(--paper))}
.d-hc-legend i[data-l="3"]{background:color-mix(in srgb,var(--ink) 58%,var(--paper))}
.d-hc-legend i[data-l="4"]{background:var(--ink)}

init:
root => {
  const svg = root.querySelector('.d-hc-svg');
  if (!svg) return;
  const weeks = 20, days = 7, cell = 14, gap = 2;
  const NS = 'http://www.w3.org/2000/svg';
  const mk = (tag, attrs) => { const el = document.createElementNS(NS, tag); for (const k in attrs) el.setAttribute(k, attrs[k]); return el; };
  const shades = ['color-mix(in srgb,var(--ink) 6%,var(--paper))', 'color-mix(in srgb,var(--ink) 18%,var(--paper))', 'color-mix(in srgb,var(--ink) 34%,var(--paper))', 'color-mix(in srgb,var(--ink) 58%,var(--paper))', 'var(--ink)'];
  let seed = 11;
  const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
  const days7 = ['一', '三', '五', '日'];
  for (let w = 0; w < weeks; w++) {
    for (let d = 0; d < days; d++) {
      const r = rnd();
      const v = d === 5 || d === 6 ? (r > .55 ? 1 : 0) : r > .82 ? 4 : r > .62 ? 3 : r > .38 ? 2 : r > .16 ? 1 : 0;
      const rect = mk('rect', { class: 'd-hc-cell', x: 22 + w * (cell + gap), y: 6 + d * (cell + gap), width: cell, height: cell, rx: 2, fill: shades[v] });
      svg.appendChild(rect);
    }
  }
  days7.forEach((label, k) => {
    const t = mk('text', { class: 'd-hc-t', x: 16, y: 6 + k * 4 * (cell + gap) + cell - 3, 'text-anchor': 'end', fill: 'var(--faint)', 'font-size': '7', 'font-family': 'var(--font-mono)' });
    t.textContent = label;
    svg.appendChild(t);
  });
}
